package org.daidai.modules.music;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.daidai.modules.shared.Ui;
import org.daidai.modules.shared.Texts;

/** My songs, playlists and URI-based metadata editing. Media reads run off the UI thread. */
public final class MusicLibraryScreen {
    public static final int PICK_LYRICS=741,PICK_COVER=742;
    private static final WeakHashMap<Activity,MusicLibraryScreen> INSTANCES=new WeakHashMap<>();
    private final Activity a;private Runnable changed;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final ArrayList<Dialog> dialogs=new ArrayList<>();private boolean scanning;
    private String pendingUri;private Runnable afterEdit;
    private MusicLibraryScreen(Activity activity,Runnable callback){a=activity;changed=callback;}
    private static MusicLibraryScreen get(Activity a,Runnable changed){MusicLibraryScreen s=INSTANCES.get(a);if(s==null){s=new MusicLibraryScreen(a,changed);INSTANCES.put(a,s);}else if(changed!=null)s.changed=changed;return s;}
    private String t(String key,Object...args){return Texts.get(a,key,args);}
    public static void open(Activity a,Runnable changed){get(a,changed).scanAndOpen();}
    public static void openPlaylists(Activity a,Runnable changed){get(a,changed).playlists();}
    public static void openFavorites(Activity a,Runnable changed){MusicLibraryScreen s=get(a,changed);s.showSongs(s.t("library_favorites"),s.tracks(MusicCollections.favorites(a)),"@favorites");}
    public static void edit(Activity a,MusicLibrary.Track track,Runnable changed){get(a,changed).editTrack(track.uri,changed);}
    public static boolean toggleFavorite(Activity a,MusicLibrary.Track track,Runnable changed){MusicLibrary.discover(a,Collections.singleton(track));boolean value=MusicCollections.toggleFavorite(a,track.uri);if(changed!=null)changed.run();return value;}
    public static boolean onActivityResult(Activity a,int request,int result,Intent data){return onActivityResult(a,request,result,data,null);}
    /** Reattaches the activity refresh callback when Android recreated it while the picker was open. */
    public static boolean onActivityResult(Activity a,int request,int result,Intent data,Runnable changed){if(request!=PICK_LYRICS&&request!=PICK_COVER)return false;return get(a,changed).result(request,result,data);}
    public static void destroy(Activity a){MusicLibraryScreen s=INSTANCES.remove(a);if(s!=null){s.worker.shutdownNow();s.main.removeCallbacksAndMessages(null);for(Dialog d:new ArrayList<>(s.dialogs))if(d.isShowing())d.dismiss();s.dialogs.clear();}}
    private LinearLayout box(){LinearLayout b=Ui.column(a);b.setPadding(Ui.dp(a,22),Ui.dp(a,10),Ui.dp(a,22),Ui.dp(a,12));return b;}
    private ScrollView scroll(LinearLayout b){ScrollView v=new ScrollView(a);v.addView(b);return v;}
    private AlertDialog dialog(String title,LinearLayout box){AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setView(scroll(box)).setNegativeButton(t("music_close"),null).create();dialogs.add(d);d.setOnDismissListener(v->dialogs.remove(d));d.show();return d;}
    private void notifyChanged(){if(changed!=null)changed.run();}
    private void scanAndOpen(){if(scanning)return;String tree=a.getSharedPreferences("music_module",0).getString("storage_tree_uri","");if(tree.isEmpty()){showSongs(t("library_my_songs"),MusicLibrary.catalogue(a),null);return;}scanning=true;ProgressDialog progress=new ProgressDialog(a);progress.setMessage(t("library_scanning"));progress.setCancelable(false);dialogs.add(progress);progress.show();worker.execute(()->{boolean failed=false;try{ArrayList<MusicLibrary.Track> scanned=MusicFolder.loadChecked(a,tree);MusicLibrary.discover(a,scanned);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}catch(Exception e){failed=true;}ArrayList<MusicLibrary.Track> rows=MusicLibrary.catalogue(a);final boolean error=failed;main.post(()->{scanning=false;if(!a.isDestroyed()){progress.dismiss();dialogs.remove(progress);showSongs(t("library_my_songs"),rows,null);if(error)Ui.note(a,t("library_my_songs"),t("library_folder_failed"));}});});}
    private void playlists(){LinearLayout b=box(),list=Ui.column(a);Runnable[] render={null};render[0]=()->{list.removeAllViews();List<String> names=MusicCollections.playlistNames(a);for(String name:names){Button row=Ui.button(list,name,()->playlistActions(name,render[0]));row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);}if(names.isEmpty())list.addView(Ui.text(a,t("library_no_playlists"),15));};Ui.button(b,t("library_create_playlist"),()->playlistName(null,render[0]));Ui.button(b,"♥ "+t("library_favorites"),()->openFavorites(a,changed));b.addView(list);render[0].run();dialog(t("library_playlists"),b);}
    private void playlistActions(String name,Runnable refresh){LinearLayout b=box();AlertDialog[] actions={null};Ui.button(b,t("library_open_playlist"),()->showSongs(name,tracks(MusicCollections.playlist(a,name)),name));Ui.button(b,t("library_rename_playlist"),()->playlistName(name,()->{if(actions[0]!=null)actions[0].dismiss();refresh.run();}));Ui.button(b,t("library_delete_playlist"),()->new AlertDialog.Builder(a).setTitle(t("library_delete_playlist")).setMessage(t("library_delete_playlist_confirm",name)).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("library_delete"),(d,w)->{MusicCollections.deletePlaylist(a,name);if(actions[0]!=null)actions[0].dismiss();refresh.run();}).show());actions[0]=dialog(name,b);}
    private ArrayList<MusicLibrary.Track> tracks(Collection<String> uris){ArrayList<MusicLibrary.Track> out=new ArrayList<>();for(String uri:uris){MusicLibrary.Track track=MusicLibrary.find(a,uri);if(track!=null)out.add(track);}return out;}
    private void playlistName(String old,Runnable saved){LinearLayout b=box();EditText name=input(b,t("library_playlist_name"),old==null?"":old,InputType.TYPE_CLASS_TEXT);AlertDialog d=new AlertDialog.Builder(a).setTitle(t(old==null?"library_create_playlist":"library_rename_playlist")).setView(b).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("music_save"),null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{boolean ok=old==null?MusicCollections.createPlaylist(a,name.getText().toString()):MusicCollections.renamePlaylist(a,old,name.getText().toString());if(!ok){name.setError(t("library_bad_playlist_name"));return;}d.dismiss();saved.run();}));d.show();}
    private void showSongs(String title,ArrayList<MusicLibrary.Track> initial,String playlist){LinearLayout b=box(),list=Ui.column(a);LinkedHashSet<String> selected=new LinkedHashSet<>();ArrayList<MusicLibrary.Track> rows=new ArrayList<>();Runnable[] render={null};render[0]=()->{rows.clear();rows.addAll(playlist==null?MusicLibrary.catalogue(a):tracks("@favorites".equals(playlist)?MusicCollections.favorites(a):MusicCollections.playlist(a,playlist)));HashSet<String> available=new HashSet<>();for(MusicLibrary.Track track:rows)available.add(track.uri);selected.retainAll(available);list.removeAllViews();if(rows.isEmpty())list.addView(Ui.text(a,t("library_no_songs"),15));for(MusicLibrary.Track track:rows){LinearLayout row=Ui.row(list);CheckBox check=new CheckBox(a);check.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.BLUE));check.setChecked(selected.contains(track.uri));check.setOnCheckedChangeListener((v,on)->{if(on)selected.add(track.uri);else selected.remove(track.uri);});row.addView(check);Button song=Ui.button(row,track.title+(track.vocalist.isEmpty()?"":" · "+track.vocalist),()->songActions(track,playlist,render[0]));LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)song.getLayoutParams();lp.width=0;lp.weight=1;song.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);}};LinearLayout controls=Ui.row(b);Ui.cell(controls,t("library_add_selected"),()->{MusicLibrary.addToQueue(a,tracks(selected));notifyChanged();Toast.makeText(a,t("library_added_to_queue"),Toast.LENGTH_SHORT).show();});Ui.cell(controls,t("library_add_all"),()->{MusicLibrary.addToQueue(a,rows);notifyChanged();Toast.makeText(a,t("library_added_to_queue"),Toast.LENGTH_SHORT).show();});Ui.button(b,t("library_add_to_playlist"),()->choosePlaylist(selected));b.addView(list);render[0].run();dialog(title,b);}
    private void songActions(MusicLibrary.Track track,String playlist,Runnable refresh){LinearLayout b=box();AlertDialog[] actions={null};Runnable updated=()->{if(actions[0]!=null)actions[0].dismiss();refresh.run();};Ui.button(b,t("music_edit_metadata"),()->editTrack(track.uri,updated));Ui.button(b,t("library_add_to_queue"),()->{MusicLibrary.addToQueue(a,Collections.singleton(track));notifyChanged();});Ui.button(b,(MusicCollections.isFavorite(a,track.uri)?"♥ ":"♡ ")+t(MusicCollections.isFavorite(a,track.uri)?"library_unfavorite":"library_favorite"),()->{MusicCollections.toggleFavorite(a,track.uri);notifyChanged();updated.run();});Ui.button(b,t("library_add_to_playlist"),()->choosePlaylist(Collections.singleton(track.uri)));if(playlist!=null)Ui.button(b,t("library_remove_from_playlist"),()->new AlertDialog.Builder(a).setMessage(t("library_remove_confirm")).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("library_remove"),(d,w)->{if("@favorites".equals(playlist)){if(MusicCollections.isFavorite(a,track.uri))MusicCollections.toggleFavorite(a,track.uri);}else MusicCollections.remove(a,playlist,Collections.singleton(track.uri));notifyChanged();updated.run();}).show());actions[0]=dialog(track.title,b);}
    private void choosePlaylist(Collection<String> uris){if(uris.isEmpty()){Toast.makeText(a,t("library_select_songs"),Toast.LENGTH_SHORT).show();return;}ArrayList<String> names=new ArrayList<>(MusicCollections.playlistNames(a));LinearLayout b=box();Ui.button(b,t("library_create_playlist"),()->playlistName(null,()->choosePlaylist(uris)));for(String name:names)Ui.button(b,name,()->{MusicCollections.add(a,name,uris);Toast.makeText(a,t("library_added_to_playlist"),Toast.LENGTH_SHORT).show();});dialog(t("library_add_to_playlist"),b);}
    private EditText input(LinearLayout b,String label,String value,int type){b.addView(Ui.text(a,label,14));EditText e=Ui.input(b,"",type);e.setText(value);e.setPadding(Ui.dp(a,13),Ui.dp(a,10),Ui.dp(a,13),Ui.dp(a,10));GradientDrawable bg=new GradientDrawable();bg.setColor(0xffedf3fd);bg.setCornerRadius(Ui.dp(a,8));e.setBackground(bg);LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)e.getLayoutParams();lp.setMargins(Ui.dp(a,3),0,Ui.dp(a,3),Ui.dp(a,8));return e;}
    private void editTrack(String uri,Runnable after){MusicLibrary.Track track=MusicLibrary.find(a,uri);if(track==null)return;LinearLayout b=box();String[] keys={"music_meta_title","music_meta_composer","music_meta_arranger","music_meta_vocalist","music_meta_notes","music_meta_tags","music_meta_bpm","music_meta_rating"};String[] values={track.title,track.composer,track.arranger,track.vocalist,track.notes,track.tags,track.bpm==0?"":Integer.toString(track.bpm),track.rating<0?"":Integer.toString(track.rating)};EditText[] fields=new EditText[8];for(int i=0;i<8;i++)fields[i]=input(b,t(keys[i]),values[i],i>=6?InputType.TYPE_CLASS_NUMBER:InputType.TYPE_CLASS_TEXT);Switch pure=new Switch(a);pure.setText(t("music_meta_instrumental"));pure.setChecked(track.instrumental);b.addView(pure);Ui.button(b,t("music_import_lrc"),()->pick(uri,PICK_LYRICS,after));Ui.button(b,t("music_import_cover"),()->pick(uri,PICK_COVER,after));AlertDialog d=new AlertDialog.Builder(a).setTitle(t("music_edit_metadata")).setView(scroll(b)).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("music_save"),null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String name=fields[0].getText().toString().trim();if(name.isEmpty()){fields[0].setError(t("library_title_required"));return;}int bpm=number(fields[6],0,1,1000),rating=number(fields[7],-1,0,10);if(bpm==-2||rating==-2)return;MusicLibrary.Track latest=MusicLibrary.find(a,uri);if(latest==null)latest=track;MusicLibrary.update(a,latest.withMeta(name,fields[3].getText().toString().trim(),fields[1].getText().toString().trim(),fields[2].getText().toString().trim(),fields[4].getText().toString().trim(),fields[5].getText().toString().trim(),bpm,rating,pure.isChecked(),latest.lrcPath,latest.coverPath));MusicLibrary.markMetadataEdited(a,uri);notifyChanged();if(after!=null)after.run();d.dismiss();}));d.show();}
    private int number(EditText input,int empty,int min,int max){String raw=input.getText().toString().trim();if(raw.isEmpty())return empty;try{int value=Integer.parseInt(raw);if(value<min||value>max)throw new Exception();return value;}catch(Exception e){input.setError(t("library_number_range",min,max));return -2;}}
    private void pick(String uri,int request,Runnable after){pendingUri=uri;afterEdit=after;a.getSharedPreferences("music_module",0).edit().putString("library_pick_uri",uri).putInt("library_pick_request",request).apply();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(request==PICK_LYRICS?"*/*":"image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{a.startActivityForResult(i,request);}catch(Exception e){a.getSharedPreferences("music_module",0).edit().remove("library_pick_uri").remove("library_pick_request").apply();Ui.error(a,e);}}
    private boolean result(int request,int result,Intent data){if(request!=PICK_LYRICS&&request!=PICK_COVER)return false;if(pendingUri==null&&a.getSharedPreferences("music_module",0).getInt("library_pick_request",0)==request)pendingUri=a.getSharedPreferences("music_module",0).getString("library_pick_uri",null);a.getSharedPreferences("music_module",0).edit().remove("library_pick_uri").remove("library_pick_request").apply();Runnable callback=afterEdit;afterEdit=null;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||pendingUri==null){pendingUri=null;return true;}String trackUri=pendingUri;pendingUri=null;Uri file=data.getData();worker.execute(()->{File dest=null;try{File dir=new File(a.getFilesDir(),request==PICK_LYRICS?"lyrics":"covers");dir.mkdirs();dest=File.createTempFile("song-",request==PICK_LYRICS?".lrc":".cover",dir);try(InputStream in=a.getContentResolver().openInputStream(file);OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();out.write(buffer,0,n);}}MusicLibrary.Track t=MusicLibrary.find(a,trackUri);if(t!=null)MusicLibrary.update(a,t.withMeta(t.title,t.vocalist,t.composer,t.arranger,t.notes,t.tags,t.bpm,t.rating,t.instrumental,request==PICK_LYRICS?dest.getAbsolutePath():t.lrcPath,request==PICK_COVER?dest.getAbsolutePath():t.coverPath));main.post(()->{if(!a.isDestroyed()){notifyChanged();if(callback!=null)callback.run();Toast.makeText(a,t("library_file_imported"),Toast.LENGTH_SHORT).show();}});}catch(Exception e){if(dest!=null)dest.delete();if(!(e instanceof InterruptedException))main.post(()->{if(!a.isDestroyed())Ui.error(a,e);});}});return true;}
}
